/**
 * Open links and Open file paths: a session with the pointer on a web address
 * or a file path in its output. The app finds both in plain terminal text
 * (src/terminal/links.ts) and registers them with xterm, which underlines
 * the one under the pointer in its own text colour; ⌘-click opens it
 * (Terminal.tsx, openTerminalLink and revealTerminalPath). The scenes show
 * that hover on real Claude Code output.
 */
import type { CaptureId } from "../../home/captures";
import type { SessionId } from "../../home/Scenes";
import type { BackdropScene } from "../../home/Backdrop";
import { CaptureTile, locate, MarkedScreen, useCapture } from "./parts";
import { TileShot } from "./frames";

/** A session's screen with the link `text` hovered. */
function HoveredLinkTile({ id, capture, text }: { id: SessionId; capture: CaptureId; text: string }) {
  const lines = useCapture(capture);
  const link = locate(lines, text);
  return (
    <CaptureTile id={id} kbd="⌘1">
      <MarkedScreen lines={lines} marks={link ? [{ ...link, style: { underline: true } }] : []} />
    </CaptureTile>
  );
}

function HoverShot({ backdrop, id, capture, text }: { backdrop: BackdropScene; id: SessionId; capture: CaptureId; text: string }) {
  return <TileShot backdrop={backdrop} session={id} tile={<HoveredLinkTile key={id} id={id} capture={capture} text={text} />} />;
}

/** The release summary's web address: the API's allowed origin, the web app on localhost. */
export function LinksShot() {
  return <HoverShot backdrop="agents" id="release" capture="release-86" text="http://localhost:3000" />;
}

/** The home path Claude Code prints under its banner: the session's folder. */
export function PathsShot() {
  return <HoverShot backdrop="devices" id="api" capture="api-86" text="~/fieldnotes/api" />;
}
